def feature(s):
    props = s.get('element_properties', {})
    numerator = 0.0
    coverage = 0.0
    for element, fraction in s.get('composition', {}).items():
        radius = props.get(element, {}).get('covalent_radius_A')
        if radius is not None and radius > 0 and fraction > 0:
            numerator += fraction * radius ** 3
            coverage += fraction
    volume = s.get('volume_per_atom_A3')
    if volume is None:
        volume = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if coverage <= 0 or volume is None or volume <= 0:
        return 0.0
    return float(4.0 * math.pi * numerator / (3.0 * coverage * volume))

def feature(s):
    props = s.get('element_properties', {})
    total = 0.0
    coverage = 0.0
    for element, fraction in s.get('composition', {}).items():
        value = props.get(element, {}).get('valence_electrons')
        if value is not None and fraction > 0:
            total += fraction * value
            coverage += fraction
    volume = s.get('volume_per_atom_A3')
    if volume is None:
        volume = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if coverage <= 0 or volume is None or volume <= 0:
        return 0.0
    return float(total / (coverage * volume))

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    props = s.get('element_properties', {})
    eneg = [props.get(p.get('element'), {}).get('eneg') for p in sites]
    occupancy = [max(0.0, float(p.get('occupancy', 1.0) or 0.0)) for p in sites]
    known_weight = sum(occupancy[i] for i in range(n) if eneg[i] is not None)
    if known_weight <= 0:
        return 0.0
    mean_eneg = sum(occupancy[i] * eneg[i] for i in range(n) if eneg[i] is not None) / known_weight
    neighbors = s.get('neighbors', [])
    nearest = [7.0] * n
    for bond in neighbors:
        i = bond['i']
        d = bond['distance_A']
        if d > 1e-8 and occupancy[bond['j']] > 0:
            nearest[i] = min(nearest[i], d)
    coordination = [0.0] * n
    for bond in neighbors:
        i = bond['i']
        d = bond['distance_A']
        if d > 1e-8 and d <= 1.25 * nearest[i] + 1e-8:
            coordination[i] += occupancy[bond['j']]
    high_sum = 0.0
    high_weight = 0.0
    low_sum = 0.0
    low_weight = 0.0
    for i in range(n):
        if eneg[i] is not None:
            if eneg[i] > mean_eneg + 1e-10:
                high_sum += occupancy[i] * coordination[i]
                high_weight += occupancy[i]
            else:
                low_sum += occupancy[i] * coordination[i]
                low_weight += occupancy[i]
    if high_weight <= 0 or low_weight <= 0:
        return 0.0
    return float(high_sum / high_weight - low_sum / low_weight)
